--
-- Table structure for table `vmware_assets`
--

DROP TABLE IF EXISTS `vmware_assets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vmware_assets` (
  `vm_id` int NOT NULL AUTO_INCREMENT COMMENT 'VM 고유 ID',
  `vm_name` varchar(255) NOT NULL COMMENT 'VM 이름 (VMList의 VM 컬럼, 변경되지 않는 고유 식별자)',
  `cluster_host` varchar(255) NOT NULL COMMENT '클러스터 대표 호스트명 (IP 또는 Domain)',
  `hostname` varchar(255) NOT NULL COMMENT '호스트명 (DNS Name 우선, VM 차순위)',
  `ip` varchar(50) NOT NULL COMMENT 'IP 주소',
  `servername` longtext COMMENT '서버명 (Annotation)',
  `cpu_cores` int DEFAULT NULL COMMENT 'CPU 코어수',
  `memory_gb` int DEFAULT NULL COMMENT '메모리 용량 (GB)',
  `parent_host` varchar(255) DEFAULT NULL COMMENT '상위 자산 (Host)',
  `os_version` varchar(255) DEFAULT NULL COMMENT 'OS 버전',
  `install_date` date DEFAULT NULL COMMENT '설치일자 (Creation Date)',
  `powerstate` varchar(50) DEFAULT NULL COMMENT '전원 상태 (poweredOn/poweredOff)',
  `status` varchar(50) DEFAULT NULL COMMENT '상태 (사용/폐기)',
  `pnum` int DEFAULT NULL COMMENT '맵핑된 자산 번호 (total_asset.pnum)',
  `last_updated` datetime DEFAULT NULL COMMENT '마지막 수정 날짜',
  `created_at` datetime DEFAULT NULL COMMENT '생성 날짜',
  PRIMARY KEY (`vm_id`),
  UNIQUE KEY `unique_vm_cluster` (`vm_name`,`cluster_host`),
  KEY `idx_vm_name` (`vm_name`),
  KEY `idx_cluster_host` (`cluster_host`),
  KEY `idx_hostname` (`hostname`),
  KEY `idx_ip` (`ip`),
  KEY `idx_pnum` (`pnum`)
) ENGINE=InnoDB AUTO_INCREMENT=2736 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='VMware 자산 현황';
/*!40101 SET character_set_client = @saved_cs_client */;

